{"compatibility":"as-is","safety_note_md":"# SafeStan Safety Note

Compatibility: as-is.

Protected data: none.

Generated files: `model_safe.stan`, `data_safe.json`.

No changes were required. The data variables `N1` and `N2` are context sizes used only to control generated-quantities simulation. No top-level data variable is scored by a sampling statement, and there are no parameters requiring priors.
","model_safe_stan":"functions {
  // Location-dispersion paramaeterization of gamma family
  real gamma_ld_lpdf(vector y, vector mu, real phi) {
    real beta = inv(phi);
    vector[num_elements(mu)] alpha = beta * mu;
    return gamma_lpdf(y | alpha, beta);
  }

  // Location-dispersion paramaeterization of gamma family
  real gamma_ld_rng(real mu, real phi) {
    real beta = inv(phi);
    real alpha = beta * mu;
    return gamma_rng(alpha, beta);
  }
}

data {
  int<lower=1> N1;
  int<lower=1> N2;
}

transformed data {
  real lambda = 0.1;
  real psi = 0.1;
  real gamma = 5;

  real mu1 = 30;
  real phi1 = 15;

  real mu2 = 70;
  real phi2 = 1;
}

generated quantities {
  array[N1] real x1;
  array[N1] real y1;

  array[N2] real x2;
  array[N2] real y2;

  for (n in 1:N1) {
    x1[n] = gamma_ld_rng(mu1, phi1);
    y1[n] = gamma_ld_rng(lambda * x1[n], psi + 0.001 * gamma * mu1);
  }

  for (n in 1:N2) {
    x2[n] = gamma_ld_rng(mu2, phi2);
    y2[n] = gamma_ld_rng(lambda * x2[n], psi + 0.001 * gamma * mu2);
  }
}
","data_safe_json":"{"N1":3,"N2":5}","protected_variables":[]}
